formDesktop = 0x00000004 // \u8BBE\u5907: \u684C\u9762\u7AEF\n//    ClientTypePlatformWeb     = 0x00000008 // \u8BBE\u5907: Web\n//    ClientTypeTechServerAPI   = 0x00000100 // \u5B9E\u73B0: \u670D\u52A1\u7AEF\u63A5\u53E3\n//    ClientTypeTechNative      = 0x00000200 // \u5B9E\u73B0: Native\n//    ClientTypeTechJS          = 0x00000400 // \u5B9E\u73B0: Javascript\n//    ClientTypeOSHarmony       = 0x00010000 // \u7CFB\u7EDF: \u9E3F\u8499\n//    ClientTypeOSAndroid       = 0x00020000 // \u7CFB\u7EDF: Android\n//    ClientTypeOSiOS           = 0x00040000 // \u7CFB\u7EDF: iOS\n//    ClientTypeOSWindows       = 0x00080000 // \u7CFB\u7EDF: Windows\n//    ClientTypeOSMacOS         = 0x00100000 // \u7CFB\u7EDF: MacOS\n//    ClientTypeOSLinux         = 0x00200000 // \u7CFB\u7EDF: Linux\n\n// \u5EFA\u7ACB\u57FA\u7840\u53C2\u6570\n//\u4E0B\u8FF0\u914D\u7F6E\u53C2\u6570\u5747\u4E3A\u793A\u4F8B\u6570\u636E\uFF0C\u8BF7\u6309\u7167\u5B9E\u9645\u9879\u76EE\u914D\u7F6E\nRXLoginNecessaryArgs args = new RXLoginNecessaryArgs();\nargs.setContext(this.getApplicationContext());\n\nargs.setChanelID("\u540E\u53F0channelid");//\u6E20\u9053id\uFF0C\u4E00\u4E2Aproduct\u53EF\u4EE5\u6709\u591A\u4E2A\u6E20\u9053\nargs.setProductID("\u540E\u53F0productid");//\u4EA7\u54C1id\uFF0C\u4E00\u4E2A\u5F00\u53D1\u8005\u8D26\u53F7\u4E0B\u53EF\u4EE5\u6709\u591A\u4E2A\u4EA7\u54C1\nargs.setCpID("1000000");//\u5F00\u53D1\u8005\u8D26\u53F7\u7684id\uFF0C\u521B\u5EFA\u4E86\u8D26\u53F7\u5C31\u6709\u8FD9\u4E2Aid\nargs.setClientType(131585);//\u5BA2\u6237\u7AEF\u7C7B\u578B\nargs.setHostUrl("https://rapi.weiletest.com");// api \u57DF\u540D\u5730\u5740\nargs.setDeviceCode(RuiXueSdk.getDeviceCode());//\u8BBE\u5907\u552F\u4E00\u6807\u8BC6\n\nargs.setUserID(HW);//cp\u65B9\u7528\u6237id\uFF0C\u7528\u6237\u6807\u8BC6\u7B26\n//\u4EE5\u4E0B\u53C2\u6570cp \u670D\u52A1\u5668\u767B\u5F55\u8FD4\u56DE\nargs.setSecret("e77c6866685bc7da673bd4830d81875c80ce8e04178380ceb2bb0ec21788e05e");\nargs.setIMToken("eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..wGs3Gp6tuC7nLWnEJ0uoHBgynBwAxAbQlvDdgjNnMg");\nargs.setRefreshToken("eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJTdGFuZGFyZENsYWltcyI6eyJleHAiOjE2NjQ5MzU1MTZ9LCJBY2NvdW50SUQiOjAsIlVzZXJJRC")\n\n//  \u6CE8\u518C\u8FDE\u63A5\u72B6\u6001\u76D1\u542C\u5668,\u7528\u4E8E\u76D1\u542C\u5F15\u64CE\u8FDE\u63A5\u60C5\u51B5\u548C\u5F15\u64CE\u767B\u5F55\u72B6\u6001\nRXIMEngine.getInstance().registerConnectObserver(new IRXConnectObserver() {\n\n    @Override\n    public void onLoginResult(final JXIMStatusMapper mapper, Throwable extra) {\n        Log.e(" === ", "onIMLoginResult: " + mapper.getErrMsg());\n        runOnUiThread(new Runnable() {//\u8BE5\u56DE\u8C03\u662F\u6267\u884C\u5728\u5B50\u7EBF\u7A0B\u4E2D\n            @Override\n            public void run() {\n                mStatusTv.append(mapper.getErrMsg() + "\\n");\n            }\n        });\n    }\n\n    @Override\n    public void onConnectSuccess(String ip, int port) {\n        mStatusTv.append("\u8FDE\u63A5\u6210\u529F\\n");\n    }\n\n    @Override\n    public void onConnectDisconnect(String ip, int port, int code, String message) {\n        mStatusTv.append("\u65AD\u5F00\u8FDE\u63A5,\u4FE1\u606F" + message + " -- \u72B6\u6001\u7801 :" + code + "\\n");\n    }\n\n    @Override\n    public void onConnectFail(String ip, int port, int code, String message) {\n        mStatusTv.append("\u8FDE\u63A5\u5931\u8D25\\n");\n    }\n});\n\n//  \u7ED1\u5B9A\u53C2\u6570\u5230\u5F15\u64CE\u5E76\u542F\u52A8,\u83B7\u53D6\u6A21\u5757\uFF0C\u542F\u52A8\u5F15\u64CE\u3002\u5982\u679C\u9891\u7E41\uFF08\u5982\uFF1A\u6309\u94AE\u4E8B\u4EF6\uFF09\u4F7F\u7528\uFF0C\u53EA\u9700\u8981\u7533\u8BF7\u4E00\u4E2A\u5168\u5C40\u53D8\u91CF\u5373\u53EF\nRXIMEngine.getInstance().catchModule(ProcessModuleInventory.BOOT).doAction(args, null);\n\n//  \u7ED1\u5B9A\u6D88\u606F\u76D1\u542C\u5668,\u76D1\u542C\u63A5\u6536\u6D88\u606F\nRXIMEngine.getInstance().registerConversationObserver(new IRXConversationObserver() {\n            @Override\n            public void onReceive(ConversationType conversationType, RXIMMessage contentMessage) {\n//                LG.e(contentMessage.toString());\n                LG.e(contentMessage.getExtend());\n                if(contentMessage.getMsgType() == MessageTypeInventory2.TEXT){\n                    TextMessageEntity entity = contentMessage.getContentEntity();\n                    LG.e(entity.toString());\n                }else if(contentMessage.getMsgType() == MessageTypeInventory2.PIC){\n                    PicMessageEntity entity = contentMessage.getContentEntity();\n                    LG.e(entity.toString());\n                }else if(contentMessage.getMsgType() == MessageTypeInventory2.AUDIO){\n                    VoiceMessageEntity entity = contentMessage.getContentEntity();\n                    LG.e(entity.toString());\n                } else if(contentMessage.getMsgType() == MessageTypeInventory2.VIDEO){\n                    VideoMessageEntity entity = contentMessage.getContentEntity();\n                    LG.e(entity.toString());\n                }else if(contentMessage.getMsgType() == MessageTypeInventory2.POSITION){\n                    LocationMessageEntity entity = contentMessage.getContentEntity();\n                    LG.e(entity.toString());\n                }else if(contentMessage.getMsgType() == MessageTypeInventory2.FACE){\n                    EmotionMessageEntity entity = contentMessage.getContentEntity();\n                    LG.e(entity.toString());\n                }else if(contentMessage.getMsgType() == MessageTypeInventory2.FILE){\n                    FileMessageEntity entity = contentMessage.getContentEntity();\n                    LG.e(entity.toString());\n                }\n                mStatusTv.append(contentMessage.getInboxID() + " --- " + contentMessage.getMsgType() + " ---- " + contentMessage.getContent() + "\\n");\n            }\n        });\n'})}),"\n",(0,i.jsxs)(n.p,{children:["SDK \u7684\u65B9\u6CD5\u8BBE\u8BA1\u90FD\u662F\u6309\u7167